#include "MCP57OutlinerExtensions.h"
#include "Scripting/OutlinerScriptingObject.h"
#include "MVVM/Extensions/IOutlinerExtension.h"
void UMCP57OutlinerExtensions::SetExpansion(USequencerOutlinerScriptingObject* Outliner, const TArray<FSequencerViewModelScriptingStruct>& Nodes, bool bExpanded)
{
    if (!Outliner) return;
    for (const auto& Node : Nodes)
    {
        UE::Sequencer::TViewModelPtr<UE::Sequencer::IOutlinerExtension> Item = Node.WeakViewModel.ImplicitPin();
        if (Item) Item->SetExpansion(bExpanded);
    }
}
bool UMCP57OutlinerExtensions::IsExpanded(USequencerOutlinerScriptingObject* Outliner, FSequencerViewModelScriptingStruct Node)
{
    UE::Sequencer::TViewModelPtr<UE::Sequencer::IOutlinerExtension> Item = Node.WeakViewModel.ImplicitPin();
    return Outliner && Item && Item->IsExpanded();
}

