IMPLEMENT_SIMPLE_AUTOMATION_TEST(FClothPort57Test,"AI.Toolsets.Cloth57.BindingConversion",EAutomationTestFlags::EditorContext|EAutomationTestFlags::EngineFilter)
bool FClothPort57Test::RunTest(const FString& Parameters)
{
    // 원본 메시를 복제한 임시 객체에서 섹션 바인딩과 변환을 검증한다.
    auto* Source = LoadObject<USkeletalMesh>(nullptr, TEXT("/Engine/EditorMeshes/SkeletalMesh/DefaultSkeletalMesh.DefaultSkeletalMesh"));
    if (!TestNotNull(TEXT("source mesh"), Source)) return false;
    TStrongObjectPtr<USkeletalMesh> Mesh(DuplicateObject<USkeletalMesh>(Source, GetTransientPackage()));
    auto* Factory = NewObject<UClothingAssetFactory>();
    FSkeletalMeshClothBuildParams Params;
    Params.AssetName=TEXT("MCP57_ClothingProbe"); Params.LodIndex=0; Params.SourceSection=0; Params.bRemoveFromMesh=false;
    auto* Clothing = Factory->CreateFromSkeletalMesh(Mesh.Get(), Params);
    if (!TestNotNull(TEXT("legacy cloth fixture"), Clothing)) return false;
    const FString Path=Mesh->GetPathName();
    const FString Name=Clothing->GetName();
    if (!Mesh->GetMeshClothingAssets().Contains(Clothing)) Mesh->AddClothingAsset(Clothing);
    TestTrue(TEXT("list clothing"), UChaosClothAssetToolset::ListClothingAssets(Path).Num()>0);
    TestTrue(TEXT("bind section"), UChaosClothAssetToolset::AssignClothingToSection(Path,Name,0,0,0));
    TestEqual(TEXT("read section"), UChaosClothAssetToolset::GetSectionClothing(Path,0,0),Name);
    TestTrue(TEXT("remove section"), UChaosClothAssetToolset::RemoveClothingFromSection(Path,0,0));
    TestTrue(TEXT("cleared section"), UChaosClothAssetToolset::GetSectionClothing(Path,0,0).IsEmpty());
    const FString Converted = UChaosClothAssetToolset::ConvertClothingAssetCommonToChaosClothAsset(Path,Name,TEXT("/Game/__MCP57Tests"),TEXT("CA_ConvertedProbe"));
    TestFalse(TEXT("convert legacy cloth"),Converted.IsEmpty());
    if (!Converted.IsEmpty()) TestTrue(TEXT("create cloth binding asset"),UChaosClothAssetToolset::CreateClothingAsset(Path,Converted).Num()>0);
    return true;
}
