// 지정 섹션의 바인딩만 제거하고 다른 섹션의 매핑은 그대로 보존한다.
static void UnbindSection57(UClothingAssetBase* Asset, USkeletalMesh* Mesh, int32 Lod, int32 SectionIndex)
{
    Mesh->PreEditChange(nullptr);
    auto& Model = Mesh->GetImportedModel()->LODModels[Lod];
    auto& Section = Model.Sections[SectionIndex];
    Section.ClothingData.AssetGuid = FGuid();
    Section.ClothingData.AssetLodIndex = INDEX_NONE;
    Section.CorrespondClothAssetIndex = INDEX_NONE;
    Section.ClothMappingDataLODs.Empty();
    if (auto UserData = Model.UserSectionsData.Find(Section.OriginalDataSectionIndex))
    {
        UserData->CorrespondClothAssetIndex = INDEX_NONE;
        UserData->ClothingData.AssetGuid = FGuid();
        UserData->ClothingData.AssetLodIndex = INDEX_NONE;
    }
    ClothingAssetUtils::ClearLODBiasMappings(*Mesh, Lod, SectionIndex);
    if (auto Common = Cast<UClothingAssetCommon>(Asset))
    {
        const bool bStillBound = Model.Sections.ContainsByPredicate([Asset](const FSkelMeshSection& Other)
        { return Other.ClothingData.AssetGuid == Asset->GetAssetGuid(); });
        if (!bStillBound && Common->LodMap.IsValidIndex(Lod)) Common->LodMap[Lod] = INDEX_NONE;
    }
}

