TArray<FString> UConversationReflection57::GetEntries(UConversationDatabase* Database)
{
    TArray<FString> Result;
    auto Property=FindFProperty<FArrayProperty>(UConversationDatabase::StaticClass(),TEXT("EntryTags"));
    if (Database && Property)
    {
        FScriptArrayHelper Array(Property,Property->ContainerPtrToValuePtr<void>(Database));
        for (int32 I=0;I<Array.Num();++I)
        {
            FString Text;
            Property->Inner->ExportTextItem_Direct(Text,Array.GetRawPtr(I),nullptr,Database,PPF_None);
            Result.Add(Text);
        }
    }
    return Result;
}
TMap<FGuid,UConversationNode*> UConversationReflection57::GetReachableNodes(UConversationDatabase* Database)
{
    TMap<FGuid,UConversationNode*> Result;
    if (Database) for (const auto& Pair : Database->GetFullNodeMap()) if (Database->IsNodeReachable(Pair.Key) && Pair.Value) Result.Add(Pair.Key,Pair.Value);
    return Result;
}
