TArray<FString> UMCP57DataflowImportLibrary::ImportNodeProperties(UDataflowEdNode* Node, const FString& PropertiesJson)
{
    TArray<FString> Errors;
    TSharedPtr<FJsonObject> Properties;
    if (!Node || !Node->GetDataflowNode() || !FJsonSerializer::Deserialize(TJsonReaderFactory<>::Create(PropertiesJson), Properties)) return {TEXT("Invalid node or JSON")};
    auto DataNode = Node->GetDataflowNode();
    UScriptStruct* Struct = nullptr;
    const FString StructName = DataNode->GetType().ToString().RightChop(1);
    for (TObjectIterator<UScriptStruct> It; It; ++It) if (It->GetName() == StructName) { Struct = *It; break; }
    if (!Struct) return {TEXT("Node struct missing")};
    Node->Modify();
    for (const auto& Pair : Properties->Values)
    {
        // 동적 변수 저장소는 현재 그래프의 변수로 다시 연결한다.
        if (Pair.Key == TEXT("VariablePropertyBag")) continue;
        FProperty* Property = Struct->FindPropertyByName(FName(*Pair.Key));
        if (!Property || !Property->ImportText_Direct(*Pair.Value->AsString(), Property->ContainerPtrToValuePtr<void>(DataNode.Get()), Node, PPF_None)) Errors.Add(Pair.Key);
    }
    if (auto Variable = DataNode->AsType<FGetDataflowVariableNode>()) Variable->SetVariable(UDataflow::GetDataflowAssetFromEdGraph(Node->GetGraph()), Variable->GetVariableName());
    Node->UpdatePinsFromDataflowNode();
    Node->GetGraph()->NotifyGraphChanged();
    Node->MarkPackageDirty();
    return Errors;
}

