// 5.7 변형 값의 모드와 바이트 크기를 선언된 Niagara 형식과 비교한다.
static bool IsVariantValid57(const FNiagaraVariant& Value, const FNiagaraTypeDefinition& Type)
{
    if (Type.IsDataInterface()) { return Value.GetMode() == ENiagaraVariantMode::DataInterface; }
    if (Type.IsUObject()) { return Value.GetMode() == ENiagaraVariantMode::Object; }
    return Value.GetMode() == ENiagaraVariantMode::Bytes && Value.GetNumBytes() == Type.GetSize();
}

// 에셋의 사용자 매개변수를 형식에 맞는 변형 값으로 읽는다.
static void GetParameter57(const FNiagaraParameterStore& Store, const FNiagaraVariableBase& Key, FNiagaraVariant& Value)
{
    Value = FNiagaraVariant();
    const int32 Index = Store.IndexOf(Key);
    if (Index == INDEX_NONE) { return; }
    if (Key.IsDataInterface()) { Value.SetDataInterface(Store.GetDataInterface(Index)); }
    else if (Key.IsUObject()) { Value.SetUObject(Store.GetUObject(Index)); }
    else if (Key.GetType() == FNiagaraTypeDefinition::GetPositionDef())
    {
        if (const FVector* Data = Store.GetPositionParameterValue(Key.GetName())) { Value.SetBytes(reinterpret_cast<const uint8*>(Data), sizeof(FVector)); }
    }
    else if (const uint8* Data = Store.GetParameterData(Key)) { Value.SetBytes(Data, Key.GetSizeInBytes()); }
}

// 5.7 저장소 API를 이용해 사용자 매개변수의 값과 레이아웃을 갱신한다.
static void SetParameter57(FNiagaraParameterStore& Store, const FNiagaraVariableBase& Key, const FNiagaraVariant& Value, bool bAdd = false)
{
    const bool bRebind = bAdd && Store.AddParameter(Key, false, true);
    if (Key.IsDataInterface()) { return; }
    if (Key.IsUObject()) { Store.SetUObject(Value.GetUObject(), Key); }
    else if (Key.GetType() == FNiagaraTypeDefinition::GetPositionDef())
    {
        FVector Position = FVector::ZeroVector;
        if (Value.GetMode() == ENiagaraVariantMode::Bytes && Value.GetNumBytes() == sizeof(FVector)) { FMemory::Memcpy(&Position, Value.GetBytes(), sizeof(FVector)); }
        else if (Value.GetMode() == ENiagaraVariantMode::Bytes && Value.GetNumBytes() == sizeof(FVector3f))
        {
            FVector3f PositionFloat; FMemory::Memcpy(&PositionFloat, Value.GetBytes(), sizeof(FVector3f)); Position = FVector(PositionFloat);
        }
        Store.SetPositionParameterValue(Position, Key.GetName(), bAdd);
    }
    else if (IsVariantValid57(Value, Key.GetType())) { Store.SetParameterData(Value.GetBytes(), Key, bAdd); }

}

// 데이터 인터페이스의 편집 가능한 인스턴스를 갱신하고 변경을 통지한다.
static void SetDataInterface57(UNiagaraStackFunctionInput* Input, TSubclassOf<UNiagaraDataInterface> Type, TFunction<void(UNiagaraDataInterface*)> Apply)
{
    FScopedTransaction Transaction(INVTEXT("Edit Niagara data interface"));
    Input->SetDataInterfaceValue(Type);
    UNiagaraDataInterface* Data = Input->GetDataValueObject();
    if (Data) { Data->Modify(); }
    Apply(Data);
    if (Data) { Data->PostEditChange(); Data->OnChanged().Broadcast(); }
}
static void ExtractInputPins57(FNiagaraParameterMapHistory& History, UEdGraph* FunctionGraph, FNiagaraStackGraphUtilities::ENiagaraGetStackFunctionInputPinsOptions Options, TArray<const UEdGraphPin*>& OutPins)
{
	const int32 ModuleNamespaceLength = FNiagaraConstants::ModuleNamespaceString.Len();

	for (int32 i = 0; i < History.Variables.Num(); i++)
	{
		FNiagaraVariable& Variable = History.Variables[i];
		const TArray<FNiagaraParameterMapHistory::FReadHistory>& ReadHistory = History.PerVariableReadHistory[i];

		// A read is only really exposed if it's the first read and it has no corresponding write.
		if (ReadHistory.Num() > 0 && ReadHistory[0].PreviousWritePin.Pin == nullptr)
		{
			const UEdGraphPin* InputPin = ReadHistory[0].ReadPin.Pin;

			// Make sure that the module input is from the called graph, and not a nested graph.
			UEdGraph* NodeGraph = InputPin->GetOwningNode()->GetGraph();
			if (NodeGraph == FunctionGraph)
			{
				if (Options == FNiagaraStackGraphUtilities::ENiagaraGetStackFunctionInputPinsOptions::AllInputs)
				{
					OutPins.Add(InputPin);
				}
				else
				{
					FNameBuilder InputPinName(InputPin->PinName);
					FStringView InputPinView(InputPinName);
					if (InputPinView.StartsWith(FNiagaraConstants::ModuleNamespaceString)
						&& InputPinView.Len() > ModuleNamespaceLength
						&& InputPinView[ModuleNamespaceLength] == TCHAR('.'))
					{
						OutPins.Add(InputPin);
					}
				}
			}
		}
	}
}
static bool TryGetPinDefault57(const FNiagaraVariableBase& Variable, const FNiagaraVariant& Value, FString& OutPinDefaultValue)
{
	bool bValid = IsVariantValid57(Value, Variable.GetType());
	OutPinDefaultValue.Reset();
	if (Variable.IsDataInterface())
	{
		if (bValid)
		{
			OutPinDefaultValue = FSoftObjectPath(Value.GetDataInterface()).ToString();
			return true;
		}
	}
	else if (Variable.IsUObject())
	{
		if (bValid)
		{
			OutPinDefaultValue = FSoftObjectPath(Value.GetUObject()).ToString();
			return true;
		}
	}
	else
	{
		FNiagaraVariable PinDefaultVariable = Variable;//Just deal with data in the variable since that's what other code deals with
		if (bValid)
		{
			PinDefaultVariable.AllocateData();
			FMemory::Memcpy(PinDefaultVariable.GetData(), Value.GetBytes(), PinDefaultVariable.GetType().GetSize());
		}
		else
		{
			FNiagaraEditorUtilities::ResetVariableToDefaultValue(PinDefaultVariable);
		}

		FNiagaraEditorModule& NiagaraEditorModule = FModuleManager::GetModuleChecked<FNiagaraEditorModule>("NiagaraEditor");
		TSharedPtr<INiagaraEditorTypeUtilities, ESPMode::ThreadSafe> TypeEditorUtilities = NiagaraEditorModule.GetTypeUtilities(Variable.GetType());
		if (TypeEditorUtilities.IsValid() && TypeEditorUtilities->CanHandlePinDefaults())
		{
			OutPinDefaultValue = TypeEditorUtilities->GetPinDefaultStringFromValue(PinDefaultVariable);
			return true;
		}
	}
	OutPinDefaultValue = FString();
	return false;
}

