        const FString Requested = AttributeName.TrimStartAndEnd();
        TArray<FString> Names;
        if (Requested.IsEmpty())
        {
            if (const UPCGMetadata* Metadata = Data->ConstMetadata())
            {
                TArray<FPCGAttributeIdentifier> Attributes;
                TArray<EPCGMetadataTypes> Types;
                Metadata->GetAllAttributes(Attributes, Types);
                for (const auto& Attribute : Attributes)
                {
                    const bool bDefault = Metadata->GetConstMetadataDomain(Attribute.MetadataDomain) == Metadata->GetConstDefaultMetadataDomain();
                    Names.Add(bDefault ? Attribute.Name.ToString() : TEXT("@") + Attribute.ToString());
                }
            }
        }
        else if (!PointData || !IsSupportedPointField(Requested)) Names.Add(Requested);
        for (int32 Index = StartIndex; Index < EffectiveEnd; ++Index)
        {
            auto Element = PointData && IsSupportedPointField(Requested)
                ? PointDataElementToJson(PointData, Index, Requested) : MakeShared<FJsonObject>();
            JsonObject->SetObjectField(FString::Printf(TEXT("element_%d"), Index), Element);
        }
        for (const FString& Name : Names)
        {
            auto Selector = FPCGAttributePropertySelector::CreateSelectorFromString<FPCGAttributePropertySelector>(Name);
            auto Accessor = PCGAttributeAccessorHelpers::CreateConstAccessor(Data, Selector, true);
            auto Keys = PCGAttributeAccessorHelpers::CreateConstKeys(Data, Selector);
            if (!Accessor || !Keys)
            {
                FScriptErrorBridge::RaiseScriptError(FString::Printf(TEXT("Cannot read PCG attribute '%s'."), *Name));
                return {};
            }
            bool bRead = PCGMetadataAttribute::CallbackWithRightType(Accessor->GetUnderlyingType(), [&](auto Dummy)
            {
                using T = decltype(Dummy);
                for (int32 Index = StartIndex; Index < EffectiveEnd; ++Index)
                {
                    T Value{};
                    if (!Accessor->Get<T>(Value, Index, *Keys)) return false;
                    TSharedPtr<FJsonValue> Json;
                    if constexpr (std::is_same_v<T, bool>) Json = MakeShared<FJsonValueBoolean>(Value);
                    else if constexpr (std::is_arithmetic_v<T>) Json = MakeShared<FJsonValueNumber>(static_cast<double>(Value));
                    else if constexpr (std::is_same_v<T, FString>) Json = MakeShared<FJsonValueString>(Value);
                    else if constexpr (std::is_same_v<T, FName> || std::is_same_v<T, FSoftObjectPath> || std::is_same_v<T, FSoftClassPath>) Json = MakeShared<FJsonValueString>(Value.ToString());
                    else
                    {
                        auto Object = MakeShared<FJsonObject>();
                        if (!FJsonObjectConverter::UStructToJsonObject(TBaseStructure<T>::Get(), &Value, Object, 0, 0)) return false;
                        Json = MakeShared<FJsonValueObject>(Object);
                    }
                    JsonObject->GetObjectField(FString::Printf(TEXT("element_%d"), Index))->SetField(Name, Json);
                }
                return true;
            });
            if (!bRead)
            {
                FScriptErrorBridge::RaiseScriptError(FString::Printf(TEXT("Failed to serialize PCG attribute '%s'."), *Name));
                return {};
            }
        }

		return JsonObject;
	}

