/** 5.7 콘텐츠 브라우저와 연결되는 의미 검색 창이다. */
class SSemanticSearchWindow57 : public SCompoundWidget
{
public:
    SLATE_BEGIN_ARGS(SSemanticSearchWindow57) {}
    SLATE_END_ARGS()

    /** 검색어 입력과 결과 목록을 생성할 때 호출한다. */
    void Construct(const FArguments& Args)
    {
        ChildSlot
        [
            SNew(SVerticalBox)
            + SVerticalBox::Slot().AutoHeight().Padding(8)
            [SAssignNew(Query, SEditableTextBox).HintText(FText::FromString(TEXT("찾을 에셋을 설명하세요")))]
            + SVerticalBox::Slot().AutoHeight().Padding(8)
            [SNew(SHorizontalBox)
                + SHorizontalBox::Slot().AutoWidth()
                [SNew(SButton).Text(FText::FromString(TEXT("검색"))).OnClicked(this, &SSemanticSearchWindow57::Search)]
                + SHorizontalBox::Slot().AutoWidth().Padding(8,0)
                [SNew(SButton).Text(FText::FromString(TEXT("선택 에셋과 유사한 항목"))).OnClicked(this, &SSemanticSearchWindow57::FindSimilar)]
                + SHorizontalBox::Slot().AutoWidth()
                [SNew(SButton).Text(FText::FromString(TEXT("색인 관리"))).OnClicked_Lambda([] { UE::SemanticSearch::SSemanticSearchIndexDialog::Open(); return FReply::Handled(); })]
            ]
            + SVerticalBox::Slot().AutoHeight().Padding(8)
            [SAssignNew(Status, STextBlock).AutoWrapText(true).Text(FText::FromString(TEXT("에디터 환경설정의 Semantic Search에서 모델을 연결하고 에셋을 색인하세요.")))]
            + SVerticalBox::Slot().FillHeight(1).Padding(8)
            [SAssignNew(Results, SScrollBox)]
        ];
    }

    /** 진행 중인 비동기 검색이 끝나면 에셋 목록을 갱신한다. */
    virtual void Tick(const FGeometry& Geometry, double Time, float Delta) override
    {
        SCompoundWidget::Tick(Geometry, Time, Delta);
        if (!Pending.IsValid() || !Pending->bIsComplete) { return; }
        Status->SetText(FText::FromString(Pending->Error.IsEmpty()
            ? FString::Printf(TEXT("검색 결과 %d개"), Pending->Value.Num()) : Pending->Error));
        Results->ClearChildren();
        for (const FSemanticSearchResult& Hit : Pending->Value)
        {
            const FSoftObjectPath Path = Hit.Path;
            Results->AddSlot()
            [SNew(SVerticalBox)
                + SVerticalBox::Slot().AutoHeight().Padding(0,4)
                [SNew(SButton).Text(FText::FromString(Path.ToString())).OnClicked_Lambda([Path]
                    {
                        FContentBrowserModule& Browser = FModuleManager::LoadModuleChecked<FContentBrowserModule>("ContentBrowser");
                        const FAssetData Asset = FModuleManager::LoadModuleChecked<FAssetRegistryModule>("AssetRegistry").Get().GetAssetByObjectPath(Path);
                        if (Asset.IsValid()) { Browser.Get().SyncBrowserToAssets(TArray<FAssetData>{Asset}); }
                        return FReply::Handled();
                    })]
                + SVerticalBox::Slot().AutoHeight()
                [SNew(STextBlock).Text(FText::FromString(Hit.Caption)).AutoWrapText(true)]
            ];
        }
        Pending.Reset();
    }

private:
    /** 입력된 자연어로 의미 검색을 시작한다. */
    FReply Search()
    {
        Pending.Reset(USemanticSearchToolset::Search(Query->GetText().ToString(), {}, {}, 30));
        Status->SetText(FText::FromString(TEXT("검색 중…")));
        return FReply::Handled();
    }
    /** 콘텐츠 브라우저에서 선택한 첫 번째 에셋의 유사 검색을 시작한다. */
    FReply FindSimilar()
    {
        TArray<FAssetData> Selected;
        FModuleManager::LoadModuleChecked<FContentBrowserModule>("ContentBrowser").Get().GetSelectedAssets(Selected);
        if (Selected.IsEmpty())
        {
            Status->SetText(FText::FromString(TEXT("콘텐츠 브라우저에서 에셋을 선택하세요.")));
            return FReply::Handled();
        }
        Pending.Reset(USemanticSearchToolset::FindSimilar(Selected[0].GetSoftObjectPath(), {}, {}, 30));
        Status->SetText(FText::FromString(TEXT("유사 에셋 검색 중…")));
        return FReply::Handled();
    }
    /** 검색 버튼을 누를 때 읽을 자연어 입력란이다. */
    TSharedPtr<SEditableTextBox> Query;
    /** 검색 진행 상태와 설정 오류를 표시하는 텍스트다. */
    TSharedPtr<STextBlock> Status;
    /** 검색이 완료되면 결과 버튼을 표시할 스크롤 영역이다. */
    TSharedPtr<SScrollBox> Results;
    /** 검색 완료 전 결과 객체가 수거되지 않도록 보관한다. */
    TStrongObjectPtr<USemanticSearchAsyncResult> Pending;
};

// 모듈 종료 시 시작 콜백을 해제하기 위해 핸들을 보관한다.
static FDelegateHandle SemanticSearchStartupHandle57;
void RegisterSemanticSearchWindow57()
{
    SemanticSearchStartupHandle57 = UToolMenus::RegisterStartupCallback(FSimpleMulticastDelegate::FDelegate::CreateLambda([]
    {
        FToolMenuOwnerScoped Owner("SemanticSearchWindow57");
        UToolMenu* Menu = UToolMenus::Get()->ExtendMenu("LevelEditor.MainMenu.Tools");
        Menu->FindOrAddSection("SemanticSearch").AddMenuEntry("SemanticSearch57", FText::FromString(TEXT("Semantic Search")),
            FText::FromString(TEXT("의미 검색, 유사 에셋 검색 및 색인 관리")), FSlateIcon(), FUIAction(FExecuteAction::CreateLambda([]
            {
                TSharedRef<SWindow> Window = SNew(SWindow).Title(FText::FromString(TEXT("Semantic Search"))).ClientSize(FVector2D(780,560));
                Window->SetContent(SNew(SSemanticSearchWindow57));
                FSlateApplication::Get().AddWindow(Window);
            })));
    }));
}

void UnregisterSemanticSearchWindow57()
{
    UToolMenus::UnRegisterStartupCallback(SemanticSearchStartupHandle57);
    SemanticSearchStartupHandle57.Reset();
    UToolMenus::UnregisterOwner("SemanticSearchWindow57");
}

