    {
        const FBlueprintExceptionInfo Error(EBlueprintExceptionType::UserRaisedError, FText::FromString(Message));
        FBlueprintCoreDelegates::ThrowScriptException(Frame->Object, *Frame, Error);
    }
}

		// 5.7에서는 공개된 컴포넌트 조회 API로 합성 변수 참조를 갱신한다.
        if (UWidget* Widget = WidgetBlueprint->WidgetTree->FindWidget(NewWidgetName))
        {
            for (UUIComponent* Component : Extension->GetComponentsFor(Widget))
