                    UUIComponentContainer::GetPropertyNameForComponent(Component, OldWidgetName),
                    UUIComponentContainer::GetPropertyNameForComponent(Component, NewWidgetName));
            }
        }

// 5.7의 AddComponent는 입력을 검증하지 않으므로 UObject 생성 전에 확인한다.
if (!WidgetBlueprint || !WidgetBlueprint->WidgetTree || !WidgetBlueprint->WidgetTree->FindWidget(WidgetName)
	|| !ComponentClass || !ComponentClass->IsChildOf(UUIComponent::StaticClass())
	|| ComponentClass->HasAnyClassFlags(CLASS_Abstract | CLASS_Deprecated | CLASS_NewerVersionExists))
{
	OutErrorMessage = LOCTEXT("InvalidMCP57Component", "A valid widget and a concrete UI component class are required.");
