}

// 5.8과 동일하게 동일 클래스 및 상속 관계의 중복 컴포넌트를 거부한다.
for (const UUIComponent* Existing : WidgetBlueprintExtension->GetComponentsFor(WidgetBlueprint->WidgetTree->FindWidget(WidgetName)))
{
	if (Existing && (Existing->IsA(ComponentClass) || ComponentClass->IsChildOf(Existing->GetClass())))
	{
		OutErrorMessage = LOCTEXT("MCP57ComponentHierarchyConflict", "A UI component in the same class hierarchy already exists on this widget.");
		return nullptr;
	}
}
UUIComponent* ComponentArchetype = WidgetBlueprintExtension->AddComponent(ComponentClass, WidgetName);

	const UMVVMWidgetBlueprintExtension_View* ViewExtension = Cast<UMVVMWidgetBlueprintExtension_View>(Extension);
	const UMVVMBlueprintView* BlueprintView = ViewExtension ? ViewExtension->GetBlueprintView() : nullptr;
	if (!BlueprintView) { continue; }
auto VisitPath = [&](const FMVVMBlueprintPropertyPath& Path)
{
	if (Path.GetWidgetName() != VariableName)

		return;
	}
	for (const FMVVMBlueprintFieldPath& FieldPath : Path.GetFieldPaths())
	{
		const UClass* ParentClass = FieldPath.GetParentClass(OldClass);
		if (!ParentClass || !OldClass->IsChildOf(ParentClass))
		{
			continue;
		}
		const FName MemberName = FieldPath.GetFieldName(OldClass);
		if (MemberName.IsNone())
		{
			continue;
		}
		if (FieldPath.GetBindingKind() == EBindingKind::Function)
		{
			OutReferencedFunctions.Add(MemberName);
		}
		else
		{
			OutReferencedProperties.Add(MemberName);
		}
	}
};

auto VisitConversionFunction = [&](const UMVVMBlueprintViewConversionFunction* ConversionFunction)
{
	if (!ConversionFunction)
	{
		return;
	}

	VisitPath(ConversionFunction->GetDestinationPath());
	// 변환 함수의 저장된 핀도 위젯 멤버 참조에 포함한다.
	for (const FMVVMBlueprintPin& Pin : ConversionFunction->GetPins())
	{
		VisitPath(Pin.GetPath());
	}
};

for (const FMVVMBlueprintViewBinding& Binding : BlueprintView->GetBindings())
{
	VisitPath(Binding.SourcePath);
	VisitPath(Binding.DestinationPath);
	VisitConversionFunction(Binding.Conversion.GetConversionFunction(/*bSourceToDestination=*/ true));
	VisitConversionFunction(Binding.Conversion.GetConversionFunction(/*bSourceToDestination=*/ false));
}

// 이벤트 바인딩 참조를 수집한다.
for (const UMVVMBlueprintViewEvent* Event : BlueprintView->GetEvents())
{
	if (!Event)
	{
		continue;
	}
	VisitPath(Event->GetEventPath());
	VisitPath(Event->GetDestinationPath());
	for (const FMVVMBlueprintPin& Pin : Event->GetPins())
	{
		VisitPath(Pin.GetPath());

// 조건 바인딩의 경로와 인자 핀을 수집한다.
for (const UMVVMBlueprintViewCondition* Condition : BlueprintView->GetConditions())
{
	if (!Condition)
	{
		continue;
	}
	VisitPath(Condition->GetConditionPath());
	VisitPath(Condition->GetDestinationPath());
	for (const FMVVMBlueprintPin& Pin : Condition->GetPins())
	{
		VisitPath(Pin.GetPath());
	}
}
