/** 교체 전에 기본 사용자 위젯이 지정한 포커스 대상인지 확인한다. */
static bool MCP57IsDesiredFocusWidget(UWidgetBlueprint* Blueprint, UWidget* Widget)
{
    if (Blueprint && Blueprint->GeneratedClass && Widget)
    {
        const UUserWidget* DefaultWidget = Blueprint->GeneratedClass->GetDefaultObject<UUserWidget>();
        return DefaultWidget && DefaultWidget->GetDesiredFocusWidgetName() == Widget->GetFName();
    }
    return false;
}

/** 위젯 교체 시 트리 안에서 충돌하지 않는 새 이름을 만든다. */
static FString MCP57FindNextValidName(UWidgetTree* Tree, const FString& Name)
{
    if (!FindObject<UObject>(Tree, *Name)) { return Name; }
    FString Base = Name;
    int32 Split = INDEX_NONE;
    if (Base.FindLastChar(TEXT('_'), Split) && Base.Mid(Split + 1).IsNumeric())
    {
        Base.LeftInline(Split);
    }
    FString Result = Base;
    for (int32 Suffix = 1; FindObject<UObject>(Tree, *Result); ++Suffix)
    {
        Result = FString::Printf(TEXT("%s_%d"), *Base, Suffix);
    }
    return Result;
}
